ALTER TABLE "matches" DROP CONSTRAINT "matches_winner_requires_completion";--> statement-breakpoint
ALTER TABLE "matches" DROP CONSTRAINT "matches_scrim_end_restore_state";--> statement-breakpoint
ALTER TABLE "scrims" DROP CONSTRAINT "scrims_formation_method_required";--> statement-breakpoint
