ALTER TABLE "matches" ADD CONSTRAINT "matches_winner_requires_completion" CHECK (("matches"."status" = 'completed' and "matches"."winner_team_id" is not null) or "matches"."status" = 'ended_early' or ("matches"."status" not in ('completed', 'ended_early') and "matches"."winner_team_id" is null));--> statement-breakpoint
ALTER TABLE "matches" ADD CONSTRAINT "matches_scrim_end_restore_state" CHECK (("matches"."status_before_scrim_end" is null and "matches"."ended_at_before_scrim_end" is null and "matches"."end_reason_before_scrim_end" is null) or ("matches"."status_before_scrim_end" is not null and (("matches"."status_before_scrim_end" = 'pending' and "matches"."status" in ('cancelled', 'ended_early')) or ("matches"."status_before_scrim_end" = 'in_progress' and "matches"."status" = 'ended_early'))));--> statement-breakpoint
ALTER TABLE "scrims" ADD CONSTRAINT "scrims_early_end_restore_state" CHECK ("scrims"."ended_early_from_status" is null or ("scrims"."status" = 'ended_early' and "scrims"."ended_early_from_status" in ('preparing', 'ready', 'in_progress')));--> statement-breakpoint
ALTER TABLE "scrims" ADD CONSTRAINT "scrims_formation_method_required" CHECK ("scrims"."status" in ('recruit', 'preparing', 'cancelled') or "scrims"."formation_method" is not null or ("scrims"."status" = 'ended_early' and "scrims"."ended_early_from_status" is not null and "scrims"."ended_early_from_status" = 'preparing'));